 boolean recordUnchanged(String key,JSONObject original,String id){JSONObject live=null;JSONArray all=rows(key);for(int i=0;i<all.length();i++){JSONObject row=all.optJSONObject(i);if(row!=null&&id.equals(row.optString("id")))live=row;}boolean ok=original==null?live==null:live!=null&&live.toString().equals(original.toString());if(!ok)error("이 항목은 다른 작업에서 변경됐습니다. 입력은 유지됩니다. 최신 항목과 비교하세요.");return ok;}
