 void resumeWorkspace(String id){if(busy)return;stashWorkspace();ScrollView view=workspaces.get(id);if(view==null)return;root=(LinearLayout)view.getChildAt(0);activeWorkspaceId=id;activeWorkspaceTitle=workspaceTitles.get(id);preserveWorkspace=true;setContentView(view);}
 void chooseWorkspace(){if(busy)return;stashWorkspace();ArrayList<String> ids=new ArrayList<>(workspaces.keySet()),labels=new ArrayList<>();labels.add("업무 홈");if(can("lighting.read"))labels.add("조명 설치 · 전기 시공");final int offset=labels.size();for(String id:ids)labels.add(workspaceTitles.get(id));labels.add("현재 입력 작업 닫기");new AlertDialog.Builder(this).setTitle("열린 작업 전환 · 입력값 유지").setItems(labels.toArray(new String[0]),(d,n)->{if(n==0){dashboard();return;}if(offset==2&&n==1){businessList("lighting");return;}if(n<offset+ids.size()){resumeWorkspace(ids.get(n-offset));return;}new AlertDialog.Builder(this).setMessage("현재 작업을 닫으면 저장하지 않은 입력은 사라집니다.").setPositiveButton("닫기",(a,b)->{workspaces.remove(activeWorkspaceId);workspaceTitles.remove(activeWorkspaceId);preserveWorkspace=false;dashboard();}).setNegativeButton("취소",null).show();}).setNegativeButton("돌아가기",null).show();}
