 String host="",session="",version=null,group="dashboard",exportText="";JSONObject state=new JSONObject();LinearLayout root;int green=Color.rgb(23,53,43),background=Color.rgb(245,246,242);float fontScale=1;JSONObject account=new JSONObject();JSONArray businessDefinitions=new JSONArray();byte[] pendingPdf=null;boolean busy=false;
