 Button button(String s,Runnable fn){boolean primary=s.contains("저장")||s.contains("로그인")||s.startsWith("＋")||s.contains("계산 / 검토");Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(15*fontScale);b.setTypeface(android.graphics.Typeface.DEFAULT,1);b.setMinHeight(dp(50));b.setTextColor(primary?Color.WHITE:green);b.setBackground(surface(primary?green:Color.WHITE,primary?0:Color.rgb(219,226,216)));b.setPadding(dp(16),dp(12),dp(16),dp(12));b.setElevation(dp(1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(5));root.addView(b,lp);b.setOnClickListener(v->fn.run());return b;}
