 void error(String s){new AlertDialog.Builder(this).setTitle("오름목").setMessage(s).setPositiveButton("확인",null).show();}
 JSONObject obj(Object... pairs){JSONObject o=new JSONObject();try{for(int i=0;i<pairs.length;i+=2)o.put((String)pairs[i],pairs[i+1]);}catch(Exception e){throw new RuntimeException(e);}return o;}
 void rpc(String method,JSONObject args,Result cb){if(busy)return;final String requestSession=session;busy=true;ProgressDialog progress=ProgressDialog.show(this,"오름목","자료 처리 중…",true,false);new Thread(()->{try{URL u=new URL(host+"/rpc");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(7000);c.setReadTimeout(host.startsWith("https://")?120000:15000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream out=c.getOutputStream()){out.write(obj("method",method,"args",args,"session",requestSession).toString().getBytes("UTF-8"));}InputStream in=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(bytes.size()>1700000)throw new IOException("자료 크기 제한 초과");bytes.write(buf,0,n);}in.close();c.disconnect();JSONObject response=new JSONObject(bytes.toString("UTF-8"));if(!response.optBoolean("ok"))throw new ApiFailure(response.optString("error","요청 실패"));JSONObject value=response.getJSONObject("result");runOnUiThread(()->{busy=false;progress.dismiss();try{cb.done(value);}catch(Exception e){error(e.getMessage());}});}catch(Exception e){runOnUiThread(()->{busy=false;progress.dismiss();if(e instanceof ApiFailure&&e.getMessage()!=null&&(e.getMessage().contains("로그인이 필요")||e.getMessage().contains("자동 로그인 정보"))){clearAuto();session="";account=new JSONObject();state=new JSONObject();login();error("권한이 변경되었거나 로그인이 만료됐습니다. 다시 로그인하세요.");return;}error(e instanceof ApiFailure?e.getMessage():e instanceof java.net.SocketTimeoutException?"응답 시간이 초과됐습니다. PC 오름목을 켜고 연결 주소를 확인하세요.":e instanceof java.net.ConnectException?"PC 서버에 연결되지 않습니다. USB 연결은 역방향 연결 설정과 PC 오름목 실행 상태를 확인하세요. Wi-Fi 연결은 PC 주소를 확인하세요.":"연결 처리 실패: "+e.getMessage());});}}).start();}
 void clearAuto(){getPreferences(0).edit().putBoolean("autoLogin",false).remove("secureDevice").apply();}
 String savedDevice(){try{return SecureLogin.decrypt(getPreferences(0).getString("secureDevice",""));}catch(Exception e){return "";}}
 void resumeLogin(){String token=savedDevice();if(token.isEmpty()){clearAuto();login();return;}rpc("resume",obj("token",token),r->{account=r.getJSONObject("user");applyAppearance();session=r.getString("session");reload();});}
 void signOut(){String token=savedDevice();rpc("logout",obj("deviceToken",token),r->{});clearAuto();session="";account=new JSONObject();state=new JSONObject();login();}
 void login(){workspaces.clear();workspaceTitles.clear();preserveWorkspace=false;screen("오름목에 오신 것을 환영합니다");text("관리자 계정은 관리자 기능, 배포 계정은 허용된 업무를 사용합니다.\nPC 오름목을 실행한 뒤 USB 또는 같은 Wi-Fi로 연결하세요.");EditText h=input("PC 연결 주소 (예: http://192.168.0.10:48733)",host,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);boolean keep=getPreferences(0).getBoolean("rememberId",getPreferences(0).contains("username"));EditText u=input("아이디",keep?getPreferences(0).getString("username",""):"",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD),p=input("비밀번호","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);CheckBox rememberId=new CheckBox(this),autoLogin=new CheckBox(this);rememberId.setText("아이디 저장");autoLogin.setText("자동 로그인 (이 기기 · 최대 30일)");rememberId.setTextColor(green);autoLogin.setTextColor(green);rememberId.setChecked(keep);autoLogin.setChecked(getPreferences(0).getBoolean("autoLogin",false));root.addView(rememberId);root.addView(autoLogin);rememberId.setOnCheckedChangeListener((v,yes)->{if(!yes){autoLogin.setChecked(false);getPreferences(0).edit().putBoolean("rememberId",false).remove("username").apply();clearAuto();}});autoLogin.setOnCheckedChangeListener((v,yes)->{if(yes)rememberId.setChecked(true);else clearAuto();});text("비밀번호는 저장하지 않습니다. 자동 로그인은 개인 휴대폰에서 선택하세요.");button("연결 및 로그인",()->{host=h.getText().toString().trim().replaceAll("/+$","");try{URI uri=new URI(host);if(!(("https".equals(uri.getScheme())&&(uri.getPort()==-1||uri.getPort()==443))||("http".equals(uri.getScheme())&&uri.getPort()==48733))||uri.getHost()==null||!uri.getPath().isEmpty()||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null)throw new Exception();}catch(Exception e){error("PC 주소를 https://서버주소 또는 http://주소:48733 형식으로 입력하세요.");return;}rpc("login",obj("username",u.getText().toString().trim(),"password",p.getText().toString(),"remember",autoLogin.isChecked()),r->{account=r.getJSONObject("user");applyAppearance();session=r.getString("session");p.setText("");android.content.SharedPreferences.Editor edit=getPreferences(0).edit().putString("host",host).putBoolean("rememberId",rememberId.isChecked()).putBoolean("autoLogin",false).remove("secureDevice");if(rememberId.isChecked())edit.putString("username",u.getText().toString().trim());else edit.remove("username");if(autoLogin.isChecked())try{edit.putString("secureDevice",SecureLogin.encrypt(r.getString("deviceToken"))).putBoolean("autoLogin",true);}catch(Exception e){error("로그인은 성공했지만 자동 로그인 정보를 저장하지 못했습니다. 다음에는 직접 로그인하세요.");}edit.apply();reload();});});if(getPreferences(0).getBoolean("autoLogin",false))button("자동 로그인 다시 시도",()->{if(!h.getText().toString().trim().replaceAll("/+$","").equals(getPreferences(0).getString("host",""))){error("저장된 서버와 주소가 다릅니다. 비밀번호로 로그인하세요.");return;}resumeLogin();});}

 void reload(){rpc("load",new JSONObject(),r->{state=r.getJSONObject("state");if(r.has("user")){account=r.getJSONObject("user");applyAppearance();}version=r.isNull("version")?null:r.getString("version");list(group);});}
 JSONArray rows(String key){JSONArray a=state.optJSONArray(key);return a==null?new JSONArray():a;}
