 String[] moduleKeys={"projects","quotes","customers","materials","orders","tasks","designs","siteChecks"},moduleNames={"현장 · 수금","견적 · 수익","고객 관리","자재 · 재고","발주 관리","시공 일정","계단 3D 설계","현장 실측 · 점검"};
 void metric(String label,String value,String note){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(18),dp(16),dp(18),dp(16));card.setBackground(surface(Color.WHITE,Color.rgb(221,227,218)));TextView l=new TextView(this);l.setText(label);l.setTextColor(Color.rgb(99,115,105));l.setTextSize(13*fontScale);card.addView(l);TextView amount=new TextView(this);amount.setText(value);amount.setTextSize(25*fontScale);amount.setTextColor(green);amount.setTypeface(android.graphics.Typeface.DEFAULT,1);amount.setPadding(0,dp(7),0,dp(5));card.addView(amount);TextView sub=new TextView(this);sub.setText(note);sub.setTextSize(12*fontScale);sub.setTextColor(Color.rgb(111,124,115));card.addView(sub);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,dp(10));root.addView(card,lp);}
 void dashboard(){group="dashboard";screen("오늘의 업무");text(new java.text.SimpleDateFormat("yyyy.MM.dd",Locale.KOREA).format(new Date())+"  ·  목공과 전기, 하나의 현장으로");double contract=0,paid=0,expense=0;int ongoing=0;JSONArray ps=rows("projects");for(int i=0;i<ps.length();i++){JSONObject p=ps.optJSONObject(i);if(p==null)continue;contract+=p.optDouble("contract");paid+=p.optDouble("paid");expense+=p.optDouble("actualCost");if(!p.optString("status").equals("완료"))ongoing++;}if(can("projects.read")){metric("진행 중인 현장",ongoing+"건","등록 현장 기준");metric("받을 금액",money(contract-paid),"계약 금액 − 누적 수금");metric("수금 후 잔액",money(paid-expense),"누적 수금 − 기록 지출");}else text("관리자가 허용한 업무만 표시합니다.");button("설정 · 디자인 / 사용자 권한",()->settings());if(can("lighting.read"))button("조명 설치 · 전기 시공",()->businessList("lighting"));if(hasBusiness())button("사업 운영 · 문서",()->openBusiness());if(can("reports.read"))button("통계 · 보고서",()->showReport());label("업무 바로가기");for(int i=0;i<moduleKeys.length;i++){final String key=moduleKeys[i];if(!can(key+".read"))continue;button(moduleNames[i]+"   ·   "+rows(key).length()+"건",()->list(key));}button("새로고침",()->reload());button("로그아웃",()->signOut());text("OREUM MOK  0.12 · PC와 연결됨");}
 void list(String key){if(isBusiness(key)){businessList(key);return;}if(key.equals("dashboard")){dashboard();return;}if(!can(key+".read")){error("관리자가 허용하지 않은 메뉴입니다.");dashboard();return;}group=key;String title=key;for(int i=0;i<moduleKeys.length;i++)if(moduleKeys[i].equals(key))title=moduleNames[i];screen(title);button("‹ 업무 홈",()->dashboard());ArrayList<String> visibleKeys=new ArrayList<>(),visibleNames=new ArrayList<>();for(int i=0;i<moduleKeys.length;i++)if(can(moduleKeys[i]+".read")){visibleKeys.add(moduleKeys[i]);visibleNames.add(moduleNames[i]);}Spinner nav=select("업무 이동",visibleNames.toArray(new String[0]),title);nav.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>p){}public void onItemSelected(AdapterView<?>p,View v,int pos,long id){if(!group.equals(visibleKeys.get(pos)))list(visibleKeys.get(pos));}});text("총 "+rows(key).length()+"건 · 항목을 눌러 상세 내용을 확인하세요.");if(can(key+".write"))button("＋ 새 항목 등록",()->edit(key,null));EditText find=input("검색 · 이름 / 상태 / 메모","",InputType.TYPE_CLASS_TEXT);find.setSingleLine(true);LinearLayout records=new LinearLayout(this);records.setOrientation(1);root.addView(records,new LinearLayout.LayoutParams(-1,-2));renderRows(records,key,"");find.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){renderRows(records,key,s.toString());}public void afterTextChanged(android.text.Editable e){}});button("새로고침",()->reload());if(can("export"))button("허용 자료 JSON 백업",()->backup());text("0.12.0 · PC와 동일 자료 / 동시 수정 충돌 보호");}
 void renderRows(LinearLayout parent,String key,String query){parent.removeAllViews();JSONArray a=rows(key);int found=0;for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(r==null||!r.toString().toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;found++;LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(17),dp(16),dp(17));card.setBackground(surface(Color.WHITE,Color.rgb(219,226,216)));card.setElevation(dp(1));TextView name=new TextView(this);name.setText(r.optString("name","이름 없음")+"   ›");name.setTextSize(17*fontScale);name.setTextColor(green);name.setTypeface(android.graphics.Typeface.DEFAULT,1);card.addView(name);String sub=r.optString("status");if(key.equals("projects"))sub+=" · 미수 "+money(r.optDouble("contract")-r.optDouble("paid"));if(key.equals("materials"))sub="재고 "+r.optDouble("stock")+" "+r.optString("unit");if(key.equals("tasks"))sub=r.optString("date")+" "+r.optString("time")+" · "+r.optString("owner");if(key.equals("customers"))sub=r.optString("phone");if(key.equals("designs"))sub="3D 치수 설계 · "+r.optString("reviewStatus","검토 필요");TextView note=new TextView(this);note.setText(sub);note.setTextSize(13*fontScale);note.setTextColor(Color.rgb(104,119,108));note.setPadding(0,dp(7),0,0);card.addView(note);card.setOnClickListener(v->details(key,r));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(5),0,dp(7));parent.addView(card,lp);}if(found==0){TextView empty=new TextView(this);empty.setText(query.isEmpty()?"아직 등록된 항목이 없습니다.\n위의 새 항목 등록으로 시작하세요.":"검색 결과가 없습니다.");empty.setPadding(dp(12),dp(24),dp(12),dp(24));empty.setTextColor(green);parent.addView(empty);}}
 void detailRow(String label,String value){if(value==null||value.isEmpty())return;label(label);TextView v=new TextView(this);v.setText(value);v.setTextIsSelectable(true);v.setTextSize(16*fontScale);v.setTextColor(green);v.setPadding(dp(14),dp(13),dp(14),dp(13));v.setBackground(surface(Color.WHITE,Color.rgb(221,227,218)));root.addView(v,new LinearLayout.LayoutParams(-1,-2));}
 void details(String key,JSONObject r){if(key.equals("siteChecks")){openCheck(r);return;}if(key.equals("designs")){design(r);return;}screen(r.optString("name"));String[] fields={"status","customer","project","phone","address","source","category","stock","unit","cost","supplier","qty","date","time","owner","shape","wood","contract","paid","actualCost","note"};String[] labels={"진행 상태","고객","연결 현장","연락처","주소","문의 경로","분류","현재 재고","단위","원가 단가","공급처","수량","날짜","시간","담당자","계단 형태","목재","계약 금액","누적 수금","기록 지출","메모"};for(int i=0;i<fields.length;i++){String f=fields[i];if(!r.has(f))continue;String value=r.optString(f);if(f.equals("customer"))value=lookup("customers",value);if(f.equals("project"))value=lookup("projects",value);if(f.equals("cost")||f.equals("contract")||f.equals("paid")||f.equals("actualCost"))value=money(r.optDouble(f));detailRow(labels[i],value);}if(can(key+".write"))button("수정",()->edit(key,r));if(key.equals("projects")&&can("projects.write")&&can("transactions.write"))button("수금 / 지출 등록",()->transaction(r));if(key.equals("materials")&&can("materials.write")&&can("stockMoves.write"))button("현장 출고",()->stock(r));if(key.equals("orders")&&can("orders.write")&&can("materials.write")&&!r.optBoolean("received"))button("입고 반영",()->receive(r));if(key.equals("quotes"))button("견적 계산 확인",()->rpc("totals",r,t->error("총원가 "+money(t.getDouble("cost"))+"\n공급가액 "+money(t.getDouble("sale"))+"\nVAT 포함 "+money(t.getDouble("total"))+"\n예상 이익 "+money(t.getDouble("profit")))));if(key.equals("quotes")){if(can("projects.write"))button("승인 견적 → 현장 전환",()->rpc("convertQuote",obj("id",r.optString("id"),"version",version==null?JSONObject.NULL:version),v->{group="projects";reload();}));if(can("projects.write"))button("승인 견적을 연결 현장에 재반영",()->new AlertDialog.Builder(this).setMessage("계약액을 승인 견적으로 바꾸고 기존 수금·지출은 유지할까요?").setNegativeButton("취소",null).setPositiveButton("반영",(d,w)->rpc("convertQuote",obj("id",r.optString("id"),"refresh",true,"version",version==null?JSONObject.NULL:version),v->{group="projects";reload();})).show());if(can("export"))button("견적 PDF 저장",()->rpc("quoteView",obj("id",r.optString("id"),"export",true),v->savePdf(v.getJSONArray("lines"),"오름목-견적.pdf")));}button("목록으로",()->list(key));}

 JSONObject cloneObj(JSONObject r){try{return new JSONObject(r.toString());}catch(Exception e){throw new RuntimeException(e);}}
 JSONObject cloneState(){return cloneObj(state);}
 void save(JSONObject next,Runnable done){rpc("save",obj("state",next,"version",version==null?JSONObject.NULL:version),r->{state=r.has("state")?r.getJSONObject("state"):next;version=r.getString("version");workspaces.remove(activeWorkspaceId);workspaceTitles.remove(activeWorkspaceId);preserveWorkspace=false;done.run();});}
 void putRow(JSONObject next,String key,JSONObject row){JSONArray old=next.optJSONArray(key),out=new JSONArray();boolean found=false;if(old!=null)for(int i=0;i<old.length();i++){JSONObject item=old.optJSONObject(i);if(item!=null&&item.optString("id").equals(row.optString("id"))){out.put(row);found=true;}else out.put(item);}if(!found)out.put(row);try{next.put(key,out);}catch(Exception e){throw new RuntimeException(e);}}
 void edit(String key,JSONObject original){if(!can(key+".write")){error("편집 권한이 없습니다.");return;}if(key.equals("siteChecks")){openCheck(original);return;}if(key.equals("designs")){design(original);return;}if(key.equals("quotes")){quote(original);return;}JSONObject r=original==null?obj("id",UUID.randomUUID().toString()):cloneObj(original);if(key.equals("projects")){if(!r.has("vatRate"))objMerge(r,"vatRate",10);if(!r.has("taxMode"))objMerge(r,"taxMode","미확정");if(!r.has("costBasis"))objMerge(r,"costBasis","지출총액");}screen("입력 · "+key);preserveWorkspace=true;String[][] fields;
 if(key.equals("customers"))fields=new String[][]{{"name","고객명"},{"businessNo","사업자등록번호 (해당 시)"},{"contact","담당자"},{"phone","연락처"},{"address","주소"},{"source","유입 경로"},{"note","상담 메모"}};
 else if(key.equals("projects"))fields=new String[][]{{"name","현장명"},{"address","주소"},{"status","단계"},{"start","시작일 YYYY-MM-DD"},{"end","완료 예정일 YYYY-MM-DD"},{"category","공종"},{"paymentTerms","계약금·중도금·잔금 조건"},{"contract","계약 합계 (VAT 포함)","n"},{"taxMode","과세 기준 (포함/면세/미확정)"},{"vatRate","VAT 세율 % (예시 10)","n"},{"costBasis","원가 기준 (지출총액/확인공급가)"},{"costNet","확인한 공급가 원가","n"},{"paid","수금 누계","n"},{"actualCost","지출 누계","n"},{"note","특이사항 · AS"}};
 else if(key.equals("materials"))fields=new String[][]{{"name","자재명 / 규격"},{"category","분류"},{"unit","단위"},{"stock","재고","n"},{"min","최소 재고","n"},{"cost","매입 공급단가","n"},{"supplier","공급처"},{"note","메모"}};
 else if(key.equals("orders"))fields=new String[][]{{"name","발주명"},{"supplier","공급처"},{"qty","수량","n"},{"cost","공급단가","n"},{"date","납기 YYYY-MM-DD"},{"status","상태"},{"note","배송 메모"}};
 else fields=new String[][]{{"name","작업명"},{"date","작업일 YYYY-MM-DD"},{"time","시간 HH:mm"},{"owner","담당"},{"status","상태"},{"note","작업 내용"}};
 Map<String,EditText> controls=new HashMap<>();for(String[] f:fields){EditText c=input(f[1],r.optString(f[0],f.length>2?"0":""),f.length>2?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT);if(r.optBoolean("received")&&(f[0].equals("qty")||f[0].equals("status")))c.setEnabled(false);controls.put(f[0],c);}Map<String,Spinner> refs=new HashMap<>();if(key.equals("projects"))refs.put("customer",reference("고객","customers",r.optString("customer")));if(key.equals("orders")||key.equals("tasks"))refs.put("project",reference("현장","projects",r.optString("project")));if(key.equals("orders")){Spinner sp=reference("자재","materials",r.optString("material"));sp.setEnabled(!r.optBoolean("received"));refs.put("material",sp);}button("저장",()->{try{for(String[] f:fields){String v=controls.get(f[0]).getText().toString().trim();r.put(f[0],f.length>2?Double.parseDouble(v.isEmpty()?"0":v):v);}
 for(Map.Entry<String,Spinner>x:refs.entrySet()){String[] ids=(String[])x.getValue().getTag();r.put(x.getKey(),ids[x.getValue().getSelectedItemPosition()]);}
 if(r.optString("name").isEmpty())throw new Exception("이름을 입력하세요.");JSONObject n=cloneState();putRow(n,key,r);save(n,()->list(key));}catch(Exception e){error(e.getMessage());}});button("취소",()->list(key));}
 Spinner reference(String label,String key,String current){JSONArray a=rows(key);String[] names=new String[a.length()+1],ids=new String[a.length()+1];names[0]="미연결";ids[0]="";for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);names[i+1]=r.optString("name");ids[i+1]=r.optString("id");}Spinner sp=select(label,names,"미연결");sp.setTag(ids);for(int i=0;i<ids.length;i++)if(ids[i].equals(current))sp.setSelection(i);return sp;}
 void quote(JSONObject original){JSONObject q=original==null?obj("id",UUID.randomUUID().toString(),"date",new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()),"status","작성","items",new JSONArray()):cloneObj(original);screen("견적 · 원가 설계");preserveWorkspace=true;EditText name=input("견적명",q.optString("name"),InputType.TYPE_CLASS_TEXT);Spinner customer=reference("고객","customers",q.optString("customer"));Spinner shape=select("계단 형태",new String[]{"일자형","ㄱ자형","ㄷ자형","지그재그형","원형","골조 위 덧시공","조립식","맞춤형"},q.optString("shape","일자형"));Spinner wood=select("수종",new String[]{"오크","미송 집성목","멀바우","애쉬","월넛","기타"},q.optString("wood","오크"));Spinner led=select("LED",new String[]{"미적용","발판 하부 간접조명","측면 조명","센서 연동","맞춤 조명"},q.optString("led","미적용"));Spinner taxMode=select("판매 단가의 VAT 기준",new String[]{"별도","포함","면세","미가산"},q.optString("taxMode",q.optBoolean("vat",true)?"별도":"미가산"));EditText taxRate=input("VAT 세율 % (실제 과세 확인)",q.optString("vatRate","10"),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText discount=input("할인액 (선택 단가 금액 기준)",q.optString("discount","0"),InputType.TYPE_CLASS_NUMBER);EditText validUntil=input("견적 유효기간 YYYY-MM-DD",q.optString("validUntil"),InputType.TYPE_CLASS_TEXT);Spinner quoteStatus=select("견적 상태",new String[]{"작성","승인","거절","취소"},q.optString("status","작성"));EditText margin=input("일반 원가 목표 마진 %",q.optString("margin","30"),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);CheckBox vat=new CheckBox(this);vat.setVisibility(View.GONE);vat.setText("VAT 10% 별도 가산");vat.setChecked(q.optBoolean("vat",true));root.addView(vat);LinearLayout itemList=new LinearLayout(this);itemList.setOrientation(1);root.addView(itemList);JSONArray items=q.optJSONArray("items")==null?new JSONArray():q.optJSONArray("items");Runnable refresh=()->{itemList.removeAllViews();for(int i=0;i<items.length();i++){final int index=i;JSONObject it=items.optJSONObject(i);Button line=new Button(this);line.setText(it.optString("name")+" · "+it.optDouble("qty")+it.optString("unit")+" / 원가 "+money(it.optDouble("cost")));line.setOnClickListener(v->itemDialog(items,index,itemList));itemList.addView(line);}};itemList.setTag(refresh);refresh.run();button("＋ 견적 항목",()->itemDialog(items,-1,itemList));EditText note=input("시공 범위 · 조건 · 보증",q.optString("note"),InputType.TYPE_CLASS_TEXT);button("계산 확인 및 저장",()->{try{if(name.getText().toString().trim().isEmpty())throw new Exception("견적명을 입력하세요.");q.put("name",name.getText().toString());q.put("customer",((String[])customer.getTag())[customer.getSelectedItemPosition()]);q.put("shape",shape.getSelectedItem().toString());q.put("wood",wood.getSelectedItem().toString());q.put("led",led.getSelectedItem().toString());q.put("margin",Double.parseDouble(margin.getText().toString()));q.put("taxMode",taxMode.getSelectedItem().toString());q.put("vatRate",Double.parseDouble(taxRate.getText().toString()));q.put("discount",Double.parseDouble(discount.getText().toString()));q.put("validUntil",validUntil.getText().toString().trim());q.put("status",quoteStatus.getSelectedItem().toString());q.put("vat",vat.isChecked());q.put("items",items);q.put("note",note.getText().toString());rpc("totals",q,t->new AlertDialog.Builder(this).setTitle("견적 확인").setMessage("총원가 "+money(t.getDouble("cost"))+"\n공급가액 "+money(t.getDouble("sale"))+"\nVAT 포함 "+money(t.getDouble("total"))+"\n예상 이익 "+money(t.getDouble("profit"))).setNegativeButton("계속 편집",null).setPositiveButton("저장",(d,w)->{JSONObject n=cloneState();putRow(n,"quotes",q);save(n,()->list("quotes"));}).show());}catch(Exception e){error(e.getMessage());}});button("취소",()->list("quotes"));}
 void itemDialog(JSONArray items,int index,LinearLayout list){JSONObject it=index<0?new JSONObject():items.optJSONObject(index);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(26,10,26,10);String[] keys={"name","qty","unit","cost","sale","spec"},labels={"항목명","수량","단위","원가 단가","고정 판매단가 (선택)","규격"};EditText[] edits=new EditText[6];for(int i=0;i<6;i++){TextView label=new TextView(this);label.setText(labels[i]);box.addView(label);edits[i]=new EditText(this);edits[i].setText(it.optString(keys[i],i==1?"1":i==3?"0":""));if(i==1||i==3||i==4)edits[i].setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);box.addView(edits[i]);}AlertDialog dialog=new AlertDialog.Builder(this).setTitle("견적 항목").setView(box).setNegativeButton("취소",null).setNeutralButton(index<0?"":"삭제",(d,w)->{if(index>=0)items.remove(index);((Runnable)list.getTag()).run();}).setPositiveButton("반영",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{JSONObject row=obj("category",it.optString("category","기타"),"name",edits[0].getText().toString(),"qty",Double.parseDouble(edits[1].getText().toString()),"unit",edits[2].getText().toString(),"cost",Double.parseDouble(edits[3].getText().toString()));if(edits[4].length()>0)row.put("sale",Double.parseDouble(edits[4].getText().toString()));row.put("spec",edits[5].getText().toString());if(index<0)items.put(row);else items.put(index,row);((Runnable)list.getTag()).run();dialog.dismiss();}catch(Exception e){error("항목과 수량·단가를 확인하세요.");}}));dialog.show();}
 void transaction(JSONObject project){screen("입출금 · "+project.optString("name"));Spinner kind=select("구분",new String[]{"수금","지출"},"수금");Spinner category=select("분류",new String[]{"계약금","중도금","잔금","자재비","인건비","외주비","운반비","출장비","장비비","기타"},"기타");Spinner method=select("결제 수단",new String[]{"계좌이체","현금","카드","기타"},"계좌이체");EditText amount=input("금액 (VAT 포함)","",InputType.TYPE_CLASS_NUMBER);EditText note=input("거래 내용","",InputType.TYPE_CLASS_TEXT);button("거래 저장",()->{try{double value=Double.parseDouble(amount.getText().toString());if(value<=0)throw new Exception();JSONObject n=cloneState(),p=cloneObj(project);String k=kind.getSelectedItemPosition()==0?"paid":"actualCost";p.put(k,p.optDouble(k)+value);putRow(n,"projects",p);JSONArray ts=n.optJSONArray("transactions");if(ts==null)ts=new JSONArray();ts.put(obj("id",UUID.randomUUID().toString(),"project",p.getString("id"),"kind",k.equals("paid")?"receipt":"expense","date",new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()),"amount",value,"category",category.getSelectedItem().toString(),"method",method.getSelectedItem().toString(),"note",note.getText().toString()));n.put("transactions",ts);save(n,()->list("projects"));}catch(Exception e){error("금액을 확인하세요.");}});button("취소",()->list("projects"));}
 void stock(JSONObject material){screen("현장 출고 · "+material.optString("name"));Spinner project=reference("사용 현장","projects","");EditText qty=input("출고 수량 (재고 "+material.optDouble("stock")+")","",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText note=input("메모","",InputType.TYPE_CLASS_TEXT);button("출고 저장",()->{try{double value=Double.parseDouble(qty.getText().toString());String pid=((String[])project.getTag())[project.getSelectedItemPosition()];if(value<=0||value>material.optDouble("stock")||pid.isEmpty())throw new Exception();JSONObject n=cloneState(),m=cloneObj(material);m.put("stock",m.optDouble("stock")-value);putRow(n,"materials",m);JSONArray ms=n.optJSONArray("stockMoves");if(ms==null)ms=new JSONArray();ms.put(obj("id",UUID.randomUUID().toString(),"project",pid,"material",m.getString("id"),"qty",value,"note",note.getText().toString(),"date",new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date())));n.put("stockMoves",ms);save(n,()->list("materials"));}catch(Exception e){error("현장과 수량을 확인하세요.");}});button("취소",()->list("materials"));}
 void receive(JSONObject order){try{JSONObject n=cloneState(),o=cloneObj(order),m=null;JSONArray materials=n.getJSONArray("materials");for(int i=0;i<materials.length();i++)if(materials.getJSONObject(i).optString("id").equals(o.optString("material")))m=materials.getJSONObject(i);if(m==null||o.optDouble("qty")<=0)throw new Exception();m.put("stock",m.optDouble("stock")+o.optDouble("qty"));o.put("received",true);o.put("status","입고완료");putRow(n,"orders",o);save(n,()->list("orders"));}catch(Exception e){error("자재 연결과 수량을 확인하세요.");}}
