 void applyAppearance(){JSONObject a=account.optJSONObject("appearance");String t=a==null?"forest":a.optString("theme","forest");green=t.equals("walnut")?Color.rgb(78,53,39):t.equals("slate")?Color.rgb(38,54,75):Color.rgb(23,53,43);background=t.equals("walnut")?Color.rgb(248,244,236):t.equals("slate")?Color.rgb(242,245,249):Color.rgb(245,246,242);fontScale=a==null?1:a.optInt("size",100)/100f;}
