 void settings(){screen("설정 · 내 계정");text(account.optString("name")+" · "+(can("admin")?"관리자":"배포 사용자")+"\n서버: "+host);JSONObject a=account.optJSONObject("appearance");Spinner theme=select("디자인 테마",new String[]{"forest","walnut","slate"},a==null?"forest":a.optString("theme","forest"));text("forest 숲빛 · walnut 원목빛 · slate 청회색");Spinner size=select("글자 크기 %",new String[]{"90","100","110","120"},a==null?"100":a.optString("size","100"));theme.setEnabled(can("appearance"));size.setEnabled(can("appearance"));if(can("appearance"))button("디자인 설정 저장",()->rpc("preferences",obj("theme",theme.getSelectedItem().toString(),"size",Integer.parseInt(size.getSelectedItem().toString())),r->{account.put("appearance",r.getJSONObject("appearance"));applyAppearance();settings();}));if(can("admin")){button("배포 사용자 추가",()->createWorker());button("사용자 권한 관리",()->rpc("users",new JSONObject(),r->{JSONArray users=r.getJSONArray("users");rpc("permissionCatalog",new JSONObject(),catalog->manageUsers(users,catalog.getJSONArray("items")));}));}button("업무 홈",()->dashboard());}
 void createWorker(){screen("배포 사용자 추가");text("기본 권한은 모두 차단됩니다. 생성 후 사용자 권한 관리에서 허용할 업무를 선택하세요.");EditText u=input("아이디 (영문·숫자 3~32자)","",InputType.TYPE_CLASS_TEXT),n=input("이름","",InputType.TYPE_CLASS_TEXT),p=input("비밀번호 (10자 이상)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);button("계정 생성",()->rpc("createUser",obj("username",u.getText().toString().trim(),"name",n.getText().toString().trim(),"password",p.getText().toString(),"role","staff","permissions",new JSONArray()),r->{p.setText("");error("계정을 만들었습니다. 허용할 업무를 설정하세요.");settings();}));button("취소",()->settings());}
 void manageUsers(JSONArray all,JSONArray catalog){ArrayList<JSONObject> users=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject u=all.optJSONObject(i);if(u!=null&&!u.optString("role").equals("admin"))users.add(u);}if(users.isEmpty()){error("배포 사용자를 먼저 추가하세요.");return;}screen("사용자 권한 관리");String[] names=new String[users.size()];for(int i=0;i<names.length;i++)names[i]=users.get(i).optString("name")+" / "+users.get(i).optString("username");Spinner selected=select("배포 사용자",names,names[0]);CheckBox enabled=new CheckBox(this);enabled.setText("로그인 허용");root.addView(enabled);ArrayList<CheckBox> checks=new ArrayList<>();for(int i=0;i<catalog.length();i++){CheckBox c=new CheckBox(this);c.setText(catalog.optJSONObject(i).optString("label"));c.setTextColor(green);root.addView(c);checks.add(c);}selected.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>p){}public void onItemSelected(AdapterView<?>p,View v,int pos,long id){JSONObject u=users.get(pos);enabled.setChecked(u.optBoolean("enabled"));JSONArray permissions=u.optJSONArray("permissions");for(int i=0;i<checks.size();i++){boolean yes=false;if(permissions!=null)for(int j=0;j<permissions.length();j++)if(permissions.optString(j).equals(catalog.optJSONObject(i).optString("key")))yes=true;checks.get(i).setChecked(yes);}}});text("편집 권한은 조회를 포함합니다. 저장 즉시 해당 사용자의 기존 로그인이 해제됩니다. 현장 연결 작업은 현장 조회 권한도 필요합니다.");button("권한 저장",()->{JSONArray permissions=new JSONArray();for(int i=0;i<checks.size();i++)if(checks.get(i).isChecked())permissions.put(catalog.optJSONObject(i).optString("key"));rpc("updateUser",obj("id",users.get(selected.getSelectedItemPosition()).optString("id"),"enabled",enabled.isChecked(),"permissions",permissions),r->{error("권한을 저장했습니다. 해당 사용자는 다시 로그인하세요.");settings();});});button("설정으로",()->settings());}
 void openCheck(JSONObject original){if(original==null){rpc("checklistTemplate",new JSONObject(),r->checkEditor(obj("id",UUID.randomUUID().toString(),"name","현장 실측·시공 점검","items",r.getJSONArray("items"))));}else checkEditor(cloneObj(original));}
 void checkEditor(JSONObject record){screen("현장 실측 · 시공 점검");text("체크는 확인 기록이며 구조·법규 승인 또는 합격 판정이 아닙니다. 실측값·시험 결과·보수 사항을 메모하세요.");EditText name=input("점검표 이름",record.optString("name"),InputType.TYPE_CLASS_TEXT);Spinner project=reference("연결 현장","projects",record.optString("project"));JSONArray items=record.optJSONArray("items");ArrayList<CheckBox> flags=new ArrayList<>();ArrayList<EditText> notes=new ArrayList<>();for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);CheckBox flag=new CheckBox(this);flag.setText(item.optString("label"));flag.setTextColor(green);flag.setChecked(item.optBoolean("done"));flag.setEnabled(can("siteChecks.write"));root.addView(flag);flags.add(flag);EditText note=input("실측값 / 결과 / 보수 메모",item.optString("note"),InputType.TYPE_CLASS_TEXT);note.setEnabled(can("siteChecks.write"));notes.add(note);}EditText memo=input("전체 메모 · 고객 확인 · 사진 위치",record.optString("note"),InputType.TYPE_CLASS_TEXT);if(can("siteChecks.write"))button("점검표 저장",()->{try{String pid=((String[])project.getTag())[project.getSelectedItemPosition()];if(pid.isEmpty()){error("연결 현장을 선택하세요. 현장 조회 권한도 필요합니다.");return;}for(int i=0;i<items.length();i++){items.getJSONObject(i).put("done",flags.get(i).isChecked());items.getJSONObject(i).put("note",notes.get(i).getText().toString());}record.put("name",name.getText().toString().trim());record.put("project",pid);record.put("items",items);record.put("note",memo.getText().toString());record.put("updatedAt",new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date()));JSONObject next=cloneState();putRow(next,"siteChecks",record);save(next,()->list("siteChecks"));}catch(Exception e){error(e.getMessage());}});button("목록",()->list("siteChecks"));}

