 String[] businessKeys={"lighting","company","documents","paymentPlans","workers","labor","defects","equipment","taxRecords","overheads"};
 boolean isBusiness(String key){for(String k:businessKeys)if(k.equals(key))return true;return false;}
 boolean hasBusiness(){for(String k:businessKeys)if(can(k+".read"))return true;return false;}
 void openBusiness(){rpc("businessCatalog",new JSONObject(),r->{businessDefinitions=r.getJSONArray("modules");businessHome();});}
 void businessHome(){screen("사업 운영 · 문서");text("기획서의 현장 중심 업무 흐름: 견적 → 현장 → 문서 → 수금·원가 → 보고서");for(int i=0;i<businessDefinitions.length();i++){JSONObject m=businessDefinitions.optJSONObject(i);String key=m.optString("key");if(can(key+".read"))button(m.optString("label")+" · "+rows(key).length()+"건",()->businessList(key));}button("업무 홈",()->dashboard());}
 JSONObject definition(String key){for(int i=0;i<businessDefinitions.length();i++){JSONObject m=businessDefinitions.optJSONObject(i);if(m.optString("key").equals(key))return m;}return null;}
 void businessList(String key){if(!can(key+".read")){error("허용되지 않은 업무입니다.");return;}if(definition(key)==null){rpc("businessCatalog",new JSONObject(),r->{businessDefinitions=r.getJSONArray("modules");businessList(key);});return;}group=key;JSONObject m=definition(key);screen(m.optString("label"));if(key.equals("lighting"))text("계단 공사 연결 없이 독립 조명 공사를 등록할 수 있습니다. 예상 원가는 참고값이며 실제 입출금은 연결 현장 장부로 관리하세요. 배선·차단기 선정은 현장 조건을 별도로 검토하세요.");if(key.equals("taxRecords"))text("외부 발급·수취 내역을 기록합니다. 이 앱에서 국세청 전자 발급·전송을 수행하지 않습니다.");if(key.equals("labor"))text("일수 × 단가는 계획 비용입니다. 실제 지급은 분할 지급 예정 또는 입출금 장부에 별도로 기록합니다.");button("‹ 사업 운영",()->businessHome());if(can(key+".write"))button(key.equals("documents")?"＋ 현장에서 문서 생성":"＋ 새 항목",()->{if(key.equals("documents"))newDocument(null);else businessEdit(key,null);});JSONArray list=rows(key);for(int i=0;i<list.length();i++){JSONObject r=list.optJSONObject(i);if(r==null)continue;String sub=key.equals("documents")?r.optString("number")+" · "+r.optString("status"):key.equals("paymentPlans")?"예정 "+money(r.optDouble("amount"))+" / 미정산 "+money(r.optDouble("amount")-r.optDouble("paid")):key.equals("labor")?"계획 "+money(r.optDouble("days")*r.optDouble("rate")):r.optString("status",r.optString("date"));if(key.equals("lighting")){double cost=r.optDouble("materialCost")+r.optDouble("laborCost")+r.optDouble("otherCost");sub=r.optString("status")+" / 견적 "+money(r.optDouble("supply")+r.optDouble("tax"))+" / 예상 차액 "+money(r.optDouble("supply")-cost)+" / 입력 부하 "+(r.optDouble("quantity")*r.optDouble("watts")+r.optDouble("length")*r.optDouble("wattsPerM"))+"W";}button(r.optString("name")+"\n"+sub,()->businessDetails(key,r));}if(list.length()==0)text("아직 등록된 항목이 없습니다.");button("새로고침",()->reload());}
 void businessDetails(String key,JSONObject row){if(key.equals("documents")){rpc("documentView",obj("id",row.optString("id")),r->{screen(row.optString("number"));JSONArray lines=r.getJSONArray("lines");for(int i=0;i<lines.length();i++)text(lines.optString(i));if(can("export"))button("PDF 저장",()->rpc("documentView",obj("id",row.optString("id"),"export",true),d->savePdf(d.getJSONArray("lines"),row.optString("number")+".pdf")));if(can("documents.write")){button("재발행",()->newDocument(row));button("문서 취소 · 이력 보존",()->{EditText reason=new EditText(this);new AlertDialog.Builder(this).setTitle("취소 사유").setView(reason).setNegativeButton("닫기",null).setPositiveButton("취소 기록",(d,w)->rpc("cancelDocument",obj("id",row.optString("id"),"reason",reason.getText().toString(),"version",version==null?JSONObject.NULL:version),x->reload())).show();});}button("목록",()->businessList(key));});return;}JSONObject m=definition(key);screen(row.optString("name"));JSONArray fields=m.optJSONArray("fields");for(int i=0;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);String value=row.optString(f.optString("key"));if(f.optString("type").equals("projects"))value=lookup("projects",value);detailRow(f.optString("label"),value);}if(key.equals("paymentPlans")){detailRow("정산액 / 미정산",money(row.optDouble("paid"))+" / "+money(row.optDouble("amount")-row.optDouble("paid")));if(can("paymentPlans.write")&&can("projects.write")&&can("transactions.write")){button("실제 수금 / 지급 반영",()->settleBusiness(row));JSONArray all=rows("transactions");for(int i=0;i<all.length();i++){JSONObject t=all.optJSONObject(i);if(t==null||!t.optString("plan").equals(row.optString("id"))||t.optString("status").equals("취소"))continue;button("입력 정정 · "+t.optString("date")+" · "+money(t.optDouble("amount")),()->{EditText reason=new EditText(this);new AlertDialog.Builder(this).setTitle("장부 입력 정정 (반환 아님)").setView(reason).setNegativeButton("닫기",null).setPositiveButton("정정",(d,w)->rpc("reverseSettlement",obj("id",t.optString("id"),"reason",reason.getText().toString(),"version",version==null?JSONObject.NULL:version),v->reload())).show();});}}}if(can(key+".write")){button("수정",()->businessEdit(key,row));if(!key.equals("taxRecords"))button("삭제",()->new AlertDialog.Builder(this).setMessage("삭제할까요?").setNegativeButton("취소",null).setPositiveButton("삭제",(d,w)->{JSONObject next=cloneState();JSONArray keep=new JSONArray(),a=rows(key);for(int i=0;i<a.length();i++)if(!a.optJSONObject(i).optString("id").equals(row.optString("id")))keep.put(a.optJSONObject(i));objMerge(next,key,keep);save(next,()->businessList(key));}).show());}button("목록",()->businessList(key));}
 void businessEdit(String key,JSONObject original){if(!can(key+".write")){error("편집 권한이 없습니다.");return;}if(key.equals("company")&&original==null&&rows(key).length()>0){error("등록된 사업자 정보를 수정하세요.");return;}JSONObject record=original==null?obj("id",UUID.randomUUID().toString()):cloneObj(original),m=definition(key);screen(m.optString("label")+" · 입력");preserveWorkspace=true;JSONArray fields=m.optJSONArray("fields");LinkedHashMap<String,View> inputs=new LinkedHashMap<>();for(int i=0;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);String name=f.optString("key"),kind=f.optString("type"),value=record.optString(name);View v;if(kind.equals("projects"))v=reference(f.optString("label"),"projects",value);else if(kind.equals("select"))v=select(f.optString("label"),f.optString("options").split(","),value);else v=input(f.optString("label"),value.isEmpty()&&kind.equals("number")?"0":value,kind.equals("number")?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_TEXT);inputs.put(name,v);}button("저장",()->{try{for(int i=0;i<fields.length();i++){JSONObject f=fields.getJSONObject(i);String name=f.getString("key"),kind=f.getString("type");View v=inputs.get(name);if(kind.equals("projects"))record.put(name,((String[])v.getTag())[((Spinner)v).getSelectedItemPosition()]);else if(kind.equals("select"))record.put(name,((Spinner)v).getSelectedItem().toString());else if(kind.equals("number"))record.put(name,Double.parseDouble(((EditText)v).getText().toString()));else record.put(name,((EditText)v).getText().toString().trim());}if(!recordUnchanged(key,original,record.optString("id")))return;JSONObject next=cloneState();putRow(next,key,record);save(next,()->businessList(key));}catch(Exception e){error("입력값을 확인하세요. "+e.getMessage());}});button("취소",()->businessList(key));}
 void newDocument(JSONObject previous){screen("현장에서 문서 생성");text("발급 당시 내용을 보존합니다. 전자세금계산서 발급 기능이 아닙니다.");Spinner project=reference("현장","projects",previous==null?"":previous.optString("project"));Spinner kind=select("문서 종류",new String[]{"거래명세서","공사계약서","작업확인서","공사완료보고서","입금확인서","하자보수확인서"},previous==null?"거래명세서":previous.optString("kind"));EditText memo=input("조건 · 고객 확인 메모","",InputType.TYPE_CLASS_TEXT);final String requestId=UUID.randomUUID().toString();button("문서 생성",()->{JSONObject args=obj("project",((String[])project.getTag())[project.getSelectedItemPosition()],"kind",kind.getSelectedItem().toString(),"memo",memo.getText().toString(),"requestId",requestId,"version",version==null?JSONObject.NULL:version);if(previous!=null)objMerge(args,"reissueOf",previous.optString("id"));rpc("createDocument",args,r->{group="documents";reload();});});button("취소",()->businessList("documents"));}
 void settleBusiness(JSONObject plan){screen("실제 수금 / 지급 반영");EditText amount=input("금액 · 미정산 "+money(plan.optDouble("amount")-plan.optDouble("paid")),"",InputType.TYPE_CLASS_NUMBER);EditText date=input("거래일 YYYY-MM-DD",new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()),InputType.TYPE_CLASS_TEXT);final String requestId=UUID.randomUUID().toString();button("정산 반영",()->{try{rpc("settlePlan",obj("id",plan.optString("id"),"amount",Double.parseDouble(amount.getText().toString()),"date",date.getText().toString(),"requestId",requestId,"version",version==null?JSONObject.NULL:version),r->{group="paymentPlans";reload();});}catch(Exception e){error("금액을 확인하세요.");}});button("취소",()->businessList("paymentPlans"));}
 void savePdf(JSONArray lines,String filename)throws Exception{String[] text=new String[lines.length()];for(int i=0;i<text.length;i++)text[i]=lines.optString(i);pendingPdf=BusinessPdf.create(text);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(i,72);}
 void showReport(){rpc("businessReport",new JSONObject(),r->{screen("통계 · 보고서");text(r.optString("note"));JSONArray months=r.getJSONArray("months");for(int i=0;i<months.length();i++){JSONObject m=months.getJSONObject(i);metric(m.getString("month"),money(m.getDouble("cashBalance")),"수금 "+money(m.getDouble("receipts"))+" · 지출 "+money(m.getDouble("expenses"))+" · 공통경비 "+money(m.getDouble("overheads")));}JSONArray projects=r.getJSONArray("projects");label("공사별 참고 손익");for(int i=0;i<projects.length();i++){JSONObject p=projects.getJSONObject(i);text(p.getString("name")+"\n매출 공급가 "+money(p.getDouble("revenue"))+" / 원가 "+money(p.getDouble("cost"))+"\n참고 이익 "+money(p.getDouble("profit"))+" / "+p.getString("basis")+" / 과세 "+p.getString("taxMode"));}button("업무 홈",()->dashboard());});}
